<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
const data=ref(null),form=ref({title:'',goal:'',deadline:'',preferences:'',ai_allowed:false}),error=ref(''),acceptConstraint=ref(false),writes=useWorkflowWrite('phase')
async function load(){try{data.value=await api.flow('/phase');form.value=Object.fromEntries(Object.keys(form.value).map(k=>[k,data.value.phase?.payload[k]??form.value[k]]));form.value.deadline=form.value.deadline||''}catch(e){error.value=e.message}}
async function save(skip=false){try{await writes.send('/phase',{...form.value,deadline:form.value.deadline||null,skip_return:skip,expected_version:data.value.phase?.version||0},'PUT');await load()}catch(e){error.value=e.message}}
async function gift(){try{await writes.send('/holidays/claim',{expected_version:0});await load()}catch(e){error.value=e.message}}
async function constraint(action){try{await writes.send('/phase/'+action,{expected_version:data.value.phase.version,...(action==='accept-constraint'?{acknowledge:acceptConstraint.value}:{})});await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><div class="reading-page"><PageHeader title="近期阶段与约定" description="只影响未来的建议，不覆盖初始评估；长期奖励偏好在问卷维护。"/><p v-if="error" class="error">{{ error }}</p><p v-if="data?.return_prompt" class="card">有一段时间没记录了。可以更新近况，也可以跳过，不补造空白月份。<button class="btn" @click="save(true)">暂时跳过，30天内不再提示</button></p><form class="card" @submit.prevent="save(false)"><label>阶段<input v-model="form.title" maxlength="120"/></label><label>近期目标<textarea v-model="form.goal" maxlength="2000"/></label><label>可选期限<input type="date" v-model="form.deadline"/></label><label>近期安排与约定<textarea v-model="form.preferences" maxlength="4000"/></label><label><input type="checkbox" v-model="form.ai_allowed"/>允许作为之后主动分析的背景</label><button class="btn" :disabled="writes.busy.value">保存未来阶段</button><RouterLink to="/onboarding">维护长期奖励偏好 →</RouterLink></form><section class="card"><h2>可选阶段约定建议</h2><p>不会修改已经开始的计时合同。</p><button class="btn" :disabled="writes.busy.value||!data?.phase?.payload.ai_allowed" @click="constraint('analyze')">主动分析本次阶段约定</button><template v-if="data?.phase?.pending"><p>{{ data.phase.pending.reason }} · {{ {gentle:'温和提醒',strong:'加强提醒',strict:'严格'}[data.phase.pending.mode]||data.phase.pending.mode }}</p><label><input type="checkbox" v-model="acceptConstraint"/>我明确接受，仅用于未来新会话</label><button class="btn" :disabled="writes.busy.value||!acceptConstraint" @click="constraint('accept-constraint')">接受未来约定</button></template></section><section v-if="data?.holidays.length" class="card"><h2>本人地区今日节日</h2><p v-for="holiday in data.holidays" :key="holiday.id">{{ holiday.name }}</p><button class="btn" :disabled="writes.busy.value||data.holiday_claimed" @click="gift">{{ data.holiday_claimed?'今日礼金已领':'领取今日礼金10币（同日一次）' }}</button></section></div></template>
